using MetinAR.Map;
using MetinAR.Map.Osm;
using Xunit;
using static MapCore.Tests.MvtTestEncoder;

namespace MapCore.Tests;

/// <summary>All fixtures are self-generated by <see cref="MvtTestEncoder"/>; no provider tile bytes.</summary>
public class MvtDecodeTests
{
    private static readonly TileId Tile = new TileId(14, 9099, 5552);

    // Exterior ring must have positive surveyor area in y-down tile coords: (0,0)->(w,0)->(w,h)->(0,h).
    private static (int, int)[] Square(int x0, int y0, int x1, int y1) => new[] { (x0, y0), (x1, y0), (x1, y1), (x0, y1) };
    private static (int, int)[] SquareReversed(int x0, int y0, int x1, int y1) => new[] { (x0, y0), (x0, y1), (x1, y1), (x1, y0) };

    [Fact]
    public void Reader_DecodesLayersPropertiesAndGeometry()
    {
        byte[] bytes = new MvtTestEncoder()
            .Layer("transportation")
            .Feature(2, Geom(false, new[] { (0, 2048), (2048, 2048), (4096, 1024) }), ("class", "primary"), ("access", "no"), ("layer", 1))
            .Layer("building", 512)
            .Feature(3, Geom(true, Square(10, 10, 20, 20)), ("render_height", 12.5), ("hide_3d", false))
            .Build();

        var layers = MvtReader.Read(bytes);
        Assert.Equal(2, layers.Count);
        Assert.Equal("transportation", layers[0].Name);
        Assert.Equal(4096u, layers[0].Extent);
        Assert.Equal(2u, layers[0].Version);
        var road = layers[0].Features[0];
        Assert.Equal(MvtGeometryType.LineString, road.Type);
        Assert.Equal("primary", road.Properties["class"]);
        Assert.Equal(1.0, road.Properties["layer"]);
        Assert.Equal(new[] { 0, 2048, 4096 }, road.Parts[0].Xs);
        Assert.Equal(new[] { 2048, 2048, 1024 }, road.Parts[0].Ys);

        var b = layers[1].Features[0];
        Assert.Equal(512u, layers[1].Extent);
        Assert.Equal(12.5, b.Properties["render_height"]);
        Assert.Equal(false, b.Properties["hide_3d"]);
        Assert.True(b.Parts[0].SignedArea() > 0);
    }

    [Fact]
    public void Reader_RejectsTruncatedAndGzipData()
    {
        byte[] bytes = new MvtTestEncoder().Layer("water").Feature(3, Geom(true, Square(0, 0, 10, 10)), ("class", "lake")).Build();
        for (int cut = 1; cut < bytes.Length; cut += 3)
        {
            var truncated = bytes.Take(cut).ToArray();
            try { MvtReader.Read(truncated); }
            catch (MvtFormatException) { }
        }

        Assert.Throws<MvtFormatException>(() => MvtReader.Read(new byte[] { 0x1f, 0x8b, 8, 0 }));
        Assert.Throws<MvtFormatException>(() => MvtReader.Read(new byte[] { 0x1a, 0x7f }));
    }

    [Fact]
    public void Decoder_ClassifiesOpenMapTilesLayers()
    {
        byte[] bytes = new MvtTestEncoder()
            .Layer("water").Feature(3, Geom(true, Square(0, 0, 100, 100)), ("class", "river"))
            .Layer("water").Feature(3, Geom(true, Square(0, 0, 100, 100)), ("class", "river"), ("brunnel", "tunnel"))
            .Layer("waterway").Feature(2, Geom(false, new[] { (0, 0), (50, 50) }), ("class", "stream"))
            .Layer("landuse").Feature(3, Geom(true, Square(0, 0, 400, 400)), ("class", "residential"))
            .Layer("landuse").Feature(3, Geom(true, Square(500, 500, 900, 900)), ("class", "military"))
            .Layer("landcover").Feature(3, Geom(true, Square(0, 0, 50, 50)), ("class", "grass"), ("subclass", "park"))
            .Layer("park").Feature(3, Geom(true, Square(0, 0, 60, 60)), ("class", "nature_reserve"))
            .Layer("transportation")
                .Feature(2, Geom(false, new[] { (0, 0), (100, 0) }), ("class", "secondary"), ("brunnel", "bridge"))
                .Feature(2, Geom(false, new[] { (0, 0), (100, 0) }), ("class", "service"), ("access", "no"))
                .Feature(2, Geom(false, new[] { (0, 0), (100, 0) }), ("class", "rail"))
                .Feature(2, Geom(false, new[] { (0, 0), (100, 0) }), ("class", "minor"), ("brunnel", "tunnel"))
                .Feature(2, Geom(false, new[] { (0, 0), (100, 0) }), ("class", "ferry"))
            .Layer("building")
                .Feature(3, Geom(true, Square(0, 0, 10, 10)), ("render_height", 21.0), ("render_min_height", 3.0))
                .Feature(3, Geom(true, Square(0, 0, 10, 10)), ("hide_3d", true))
                .Feature(3, Geom(true, Square(0, 0, 10, 10)))
            .Layer("poi").Feature(1, Geom(false, new[] { (5, 5) }), ("class", "cafe"))
            .Build();

        var features = new OpenMapTilesDecoder().Decode(Tile, bytes);
        Assert.Single(features, f => f.Kind == MapFeatureKind.Water);
        Assert.Single(features, f => f.Kind == MapFeatureKind.Waterway);
        Assert.Equal(2, features.Count(f => f.Kind == MapFeatureKind.Landuse));
        Assert.True(features.Single(f => f.Kind == MapFeatureKind.Landuse && f.Class == "military").IsPrivate);
        Assert.False(features.Single(f => f.Kind == MapFeatureKind.Landuse && f.Class == "residential").IsPrivate);
        Assert.Single(features, f => f.Kind == MapFeatureKind.Landcover);
        Assert.Single(features, f => f.Kind == MapFeatureKind.Park);
        var roads = features.Where(f => f.Kind == MapFeatureKind.Road).ToList();
        Assert.Equal(2, roads.Count); // tunnel + ferry dropped
        Assert.Contains(roads, r => r.RoadClass == RoadClass.Secondary && r.IsBridge);
        Assert.Contains(roads, r => r.RoadClass == RoadClass.Service && r.IsPrivate);
        Assert.Single(features, f => f.Kind == MapFeatureKind.Rail);
        var buildings = features.Where(f => f.Kind == MapFeatureKind.Building).ToList();
        Assert.Equal(2, buildings.Count); // hide_3d dropped
        Assert.Contains(buildings, b => b.HeightMeters == 21f && b.MinHeightMeters == 3f);
        Assert.Contains(buildings, b => b.HeightMeters == OpenMapTilesDecoder.DefaultBuildingHeightMeters);
        Assert.DoesNotContain(features, f => f.Lines.Count == 0 && f.Polygons.Count == 0);
    }

    [Fact]
    public void Decoder_GroupsHolesAndNormalizesCoordinates()
    {
        byte[] bytes = new MvtTestEncoder()
            .Layer("water")
            .Feature(3, Geom(true, Square(0, 0, 4096, 4096), SquareReversed(1024, 1024, 2048, 2048), Square(3000, 3000, 3500, 3500)), ("class", "lake"))
            .Build();
        var f = new OpenMapTilesDecoder().Decode(Tile, bytes).Single();
        Assert.Equal(2, f.Polygons.Count);
        Assert.Single(f.Polygons[0].Holes);
        Assert.Empty(f.Polygons[1].Holes);
        Assert.Equal(1.0, f.Polygons[0].Exterior[1].U, 12);
        Assert.Equal(0.25, f.Polygons[0].Holes[0][0].V, 12);
    }

    [Fact]
    public void Decoder_InflatesGzipBodies()
    {
        byte[] raw = new MvtTestEncoder()
            .Layer("building")
            .Feature(3, Geom(true, Square(10, 10, 200, 200)), ("render_height", 12.0))
            .Build();
        byte[] gz;
        using (var ms = new System.IO.MemoryStream())
        {
            using (var z = new System.IO.Compression.GZipStream(ms, System.IO.Compression.CompressionLevel.Optimal, true))
            {
                z.Write(raw, 0, raw.Length);
            }

            gz = ms.ToArray();
        }

        var features = new OpenMapTilesDecoder().Decode(Tile, gz);
        Assert.Single(features);
        Assert.Equal(MapFeatureKind.Building, features[0].Kind);
    }

    [Fact]
    public void Decoder_EmptyBytes_YieldNoFeatures()
    {
        Assert.Empty(new OpenMapTilesDecoder().Decode(Tile, Array.Empty<byte>()));
    }
}
